insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('lantern-keepers-harbour', 'story', 'The Lantern Keeper''s Harbour', 'A slow evening by a sleepy northern harbour', 'Follow Ada, the harbour''s lantern keeper, on her unhurried evening round as fishing boats settle, gulls quiet down and the lights come on one by one across the water.', 'Nimbus', array['sleep-stories','coastal']::text[], array['sea','harbour','lighthouse','lanterns','cosy','evening']::text[], array['sleep','relax']::text[], '{"scene":"ocean","palette":["#0d1440","#2c3f86","#f2a98a"],"landmark":"lighthouse","moon":true,"stars":true}'::jsonb, '[{"text":"Get comfortable wherever you are. Let your shoulders drop a little, and let the day begin to loosen its grip. There is nothing you need to do now except listen, and if your mind wanders, that''s perfectly fine.","pauseSec":5},{"text":"Tonight we''re travelling to a small harbour on a northern coast, where the houses are painted the colours of seashells, and the water is so still at dusk that the boats seem to float on glass.","pauseSec":4},{"text":"Ada has kept the harbour lanterns for many years. Every evening, when the sky turns the soft blue of a mussel shell, she pulls on her wool coat, takes her small brass key from its hook, and steps out into the cool air.","pauseSec":5},{"text":"The first lantern stands at the end of the old stone pier. Ada walks there slowly. She listens to the gentle knock of hulls against the wooden posts, and the low creak of ropes stretching and relaxing with the tide.","pauseSec":5},{"text":"She opens the little glass door, trims the wick, and strikes a match. A small flame blooms, steady and golden, and its reflection drifts down into the water, wobbling softly, as if the harbour were taking a slow breath.","pauseSec":6},{"text":"Along the quay, the fishermen are coiling their nets. Someone laughs quietly. A kettle sings in a window. The gulls, who have argued all day over scraps, have tucked their heads beneath their wings and gone quiet at last.","pauseSec":6},{"text":"Ada moves to the second lantern, beside the ferry steps, and then the third, near the boathouse with the green door. Each time, the same small ritual. Open the door. Trim the wick. Strike the match. Watch the light settle.","pauseSec":7},{"text":"The air smells of salt and woodsmoke. Far out past the breakwater, the lighthouse turns its long slow beam across the sea, sweeping, resting, sweeping again, like a patient hand smoothing a blanket.","pauseSec":7},{"text":"By the time Ada reaches the last lantern, the stars are out. Not all at once, but one after another, the way the harbour lights came on. She sits for a while on the bench beside it, her hands warm in her pockets.","pauseSec":8},{"text":"The water laps quietly at the stones. The boats rock, very gently, side to side. Everything in the harbour has found its resting place for the night. The ropes are slack. The nets are folded. The kettles have gone quiet.","pauseSec":9},{"text":"Ada closes her eyes and listens to the tide. In, and out. In, and out. There is nowhere else she needs to be. And there is nowhere else you need to be either. Just here, resting, as the harbour sleeps.","pauseSec":10},{"text":"The lanterns glow softly along the water, keeping their quiet watch. You can rest now. Goodnight.","pauseSec":12}]'::jsonb, 'harbour-night', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('the-night-train-to-alder', 'story', 'The Night Train to Alder', 'A sleeper carriage winding through snowy valleys', 'A gentle journey aboard an old sleeper train, past snow-dusted pines and sleeping villages, with tea, soft blankets and the rhythm of the rails.', 'Nimbus', array['sleep-stories','journeys']::text[], array['train','snow','journey','winter','cosy']::text[], array['sleep']::text[], '{"scene":"snow","palette":["#0b1238","#33417a","#c7b9f0"],"landmark":"train","moon":true,"stars":true}'::jsonb, '[{"text":"Settle in, and let your body grow heavy. Tonight you''re boarding a night train that travels slowly through the mountains, and you have a small, warm compartment all to yourself.","pauseSec":5},{"text":"The carriage is panelled in honey-coloured wood. There''s a narrow bed made up with crisp sheets and a thick wool blanket, a little lamp with a fringed shade, and a window that frames the falling snow.","pauseSec":5},{"text":"With a soft lurch, the train begins to move. The platform lights slide away, and then the town, and soon there is only the dark shape of the hills and the hush of snow drifting past the glass.","pauseSec":6},{"text":"The wheels find their rhythm on the rails. A steady, comforting sound. Clack, clack. Clack, clack. It''s the kind of sound you stop hearing after a while, the way you stop noticing your own breathing.","pauseSec":6},{"text":"There''s a gentle knock at the door. The attendant, an older man with a kind face, brings a tray with a pot of chamomile tea and two small oat biscuits. He wishes you a restful night and slides the door closed behind him.","pauseSec":6},{"text":"You wrap your hands around the cup. The steam rises and fogs the corner of the window. Outside, the train is crossing a long stone bridge, and far below, a frozen river glints silver in the moonlight.","pauseSec":7},{"text":"You pass a sleeping village. A single window is lit in a farmhouse, and then it, too, slips behind you. Pine trees stand along the track, their branches bowed with snow, perfectly still.","pauseSec":7},{"text":"You turn down the little lamp and slip beneath the blanket. The bed is narrow but snug, and the gentle sway of the carriage rocks you, very slightly, from side to side.","pauseSec":8},{"text":"Somewhere ahead, the town of Alder is waiting, but there''s no hurry to get there. The journey is the rest. The rails hum. The snow falls. The valley sleeps beneath its white blanket.","pauseSec":9},{"text":"Clack, clack. Clack, clack. Each sound a little softer than the last. Let it carry you, deeper and deeper into rest, as the night train winds on through the quiet mountains.","pauseSec":12}]'::jsonb, 'rainy-window', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('moon-garden', 'story', 'The Moon Garden', 'Pale flowers that open only after dark', 'Wander a walled garden where night-blooming flowers unfold in the moonlight, moths drift between the hedges and an old fountain murmurs to itself.', 'Nimbus', array['sleep-stories','nature']::text[], array['garden','flowers','moon','nature','summer']::text[], array['sleep','relax']::text[], '{"scene":"meadow","palette":["#0e1235","#3a3a7e","#9fb6e8"],"landmark":"lantern","moon":true,"stars":true}'::jsonb, '[{"text":"Let yourself arrive here, in this moment. Notice the weight of your body resting, and let it be supported. Tonight we''re visiting a garden that only truly wakes up after the sun goes down.","pauseSec":5},{"text":"It sits behind an old brick wall, through a wooden gate that creaks softly as it opens. Inside, the air is warm and smells of cut grass and honeysuckle. The moon is round and bright above the treetops.","pauseSec":5},{"text":"A gravel path curls between low hedges. Along its edges grow flowers that are white and silver and palest yellow, colours that seem to glow in the moonlight. Evening primrose. Night phlox. Moonflowers as wide as saucers.","pauseSec":6},{"text":"As you watch, one of the moonflowers begins to open. It unfurls slowly, petal by petal, as though it has all the time in the world. And it does. There is no rush in the moon garden.","pauseSec":7},{"text":"Soft grey moths drift between the blossoms. They move without a sound, settling for a moment and then lifting again, like thoughts that come and go without needing anything from you.","pauseSec":7},{"text":"In the centre of the garden there''s a small stone fountain, green with moss. Its water spills over the rim in a thin, silvery ribbon and murmurs quietly into the basin below. You sit on the bench beside it.","pauseSec":7},{"text":"The stone is still warm from the day. Crickets hum in the long grass by the wall. Somewhere, a nightjar calls once, and then the garden is quiet again, apart from the patient sound of the water.","pauseSec":8},{"text":"The fragrance of the night flowers drifts around you. Breathe it in slowly. With each breath out, let yourself sink a little further into the bench, a little further into the soft summer night.","pauseSec":9},{"text":"The moon climbs higher. The flowers open wider. And you rest here, in the heart of the moon garden, held by its stillness, with nothing at all left to do.","pauseSec":12}]'::jsonb, 'summer-night', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('cabin-in-the-rain', 'story', 'A Cabin in the Rain', 'A fireside evening while rain drums on the roof', 'Shelter in a small forest cabin as a soft rain moves through the trees. A crackling stove, a creaky armchair and a pot of soup on the hob.', 'Nimbus', array['sleep-stories','nature','cosy']::text[], array['rain','cabin','forest','cosy','autumn']::text[], array['sleep','relax','stress']::text[], '{"scene":"forest","palette":["#0f1a35","#26456b","#7aa3b8"],"landmark":"cabin","stars":false}'::jsonb, '[{"text":"Make yourself comfortable. Let your breath slow down on its own, without forcing it. Tonight you''re tucked away in a small wooden cabin, deep in an old forest, while a gentle rain begins to fall.","pauseSec":5},{"text":"The cabin is simple. One room, with a woodstove in the corner, a worn rug on the floor, a shelf of books with soft, broken spines, and an armchair that has shaped itself to whoever sits in it.","pauseSec":5},{"text":"You light the stove. The kindling catches with a small crackle, and then a steady glow spreads across the logs. The room fills slowly with warmth and the faint, sweet scent of pine.","pauseSec":6},{"text":"Outside, the rain is getting heavier, but in a calm and steady way. It patters on the tin roof, drips from the eaves, and whispers through the needles of the tall firs all around.","pauseSec":6},{"text":"On the hob, a pot of vegetable soup is simmering. You stir it slowly with a wooden spoon and pour a little into a deep blue bowl. You take it to the armchair and pull a knitted blanket over your knees.","pauseSec":7},{"text":"The soup is warm and simple. Between spoonfuls, you watch the rain through the window. Droplets gather on the glass, join together, and run down in little silver paths.","pauseSec":7},{"text":"The forest outside is dark and soft. Everything is being washed and watered. The moss on the stones grows greener. The streams fill gently. The whole forest drinks the rain and rests.","pauseSec":8},{"text":"You set the empty bowl aside. The fire has settled into a quiet orange glow, and the rain on the roof has become a single, even sound, like a hush that goes on and on.","pauseSec":9},{"text":"Your eyes grow heavy. There''s nothing to do and nowhere to go. The cabin is warm, the door is closed, and the rain will keep falling, gently, all through the night, while you rest.","pauseSec":12}]'::jsonb, 'rainy-window', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('desert-stars', 'story', 'Under the Desert Stars', 'A quiet caravan camp beneath an endless sky', 'After a long day crossing the dunes, a small caravan makes camp. Mint tea, a low fire and more stars than you have ever seen.', 'Nimbus', array['sleep-stories','journeys']::text[], array['desert','stars','journey','warm','camping']::text[], array['sleep','mindfulness']::text[], '{"scene":"desert","palette":["#0a0f30","#3b2e6e","#e8a27f"],"landmark":"tent","moon":false,"stars":true}'::jsonb, '[{"text":"Let your body settle and your breathing soften. Tonight we''re far away, in a wide desert, where a small caravan has just stopped to make camp as the last light fades from the dunes.","pauseSec":5},{"text":"The sand is still warm. The camels kneel and fold their long legs beneath them with a contented sigh. The guide, a quiet woman named Samira, begins to unpack the cooking pot and a bundle of dry wood.","pauseSec":5},{"text":"The sky changes colour slowly. Apricot, then rose, then a deep violet that seems to go on forever. The dunes turn from gold to purple to the soft grey of sleeping animals.","pauseSec":6},{"text":"A small fire is lit. Samira brews mint tea in a little dented pot, pouring it from high above the glasses so that it froths. She hands you one. It''s sweet, and fragrant, and very warm.","pauseSec":7},{"text":"As the fire burns lower, the stars appear. First a handful. Then dozens. Then so many that the sky looks dusted with sugar, and the faint, pale river of the Milky Way stretches from one horizon to the other.","pauseSec":7},{"text":"You lie back on a woven rug, your head resting on a soft cushion. The air is cooler now. A gentle breeze moves across the sand, carrying the faint sound of grains shifting, like a whisper.","pauseSec":8},{"text":"You watch the stars and let your thoughts drift. Each one is so far away, and so patient. They''ve been shining for longer than anyone can imagine, and they''re in no hurry at all.","pauseSec":9},{"text":"The fire crackles softly. A camel shifts in its sleep. The desert is vast and still and peaceful, and you are resting at the very centre of it, safe and warm beneath the endless sky. Goodnight.","pauseSec":12}]'::jsonb, 'night-wind', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('library-after-hours', 'story', 'The Library After Hours', 'Lamplight, rain and a thousand quiet books', 'Stay behind after closing in a grand old library, where the reading lamps glow green, rain taps the tall windows and the pages rustle softly.', 'Nimbus', array['sleep-stories','cosy']::text[], array['library','books','rain','cosy','city']::text[], array['sleep','focus']::text[], '{"scene":"night","palette":["#0b1130","#24305f","#b38fd8"],"landmark":"lantern","moon":true,"stars":true}'::jsonb, '[{"text":"Get comfortable and let your eyes close if you''d like. Tonight, you''ve been given a rare gift: the librarian has let you stay after closing, in the oldest library in the city.","pauseSec":5},{"text":"The great doors have been locked. The last visitors have gone home. The reading room is vast and quiet, with a high painted ceiling and long oak tables lit by little green-shaded lamps.","pauseSec":5},{"text":"Rain taps softly against the tall arched windows. Far below, the streets shine wet beneath the streetlights, and the occasional bus hums by, its sound softened by the thick stone walls.","pauseSec":6},{"text":"You wander along the shelves, letting your fingertips trail across the spines. Leather and cloth and paper. Atlases, poetry, old books about birds and stars and gardens.","pauseSec":7},{"text":"You choose one at random, a book about the clouds, with soft watercolour illustrations, and carry it to a deep armchair beneath a lamp. The pages smell of dust and vanilla.","pauseSec":7},{"text":"You turn the pages slowly. Cirrus, like brushstrokes. Cumulus, like sheep. Stratus, like a blanket pulled over the sky. You don''t need to read every word. The pictures are enough.","pauseSec":8},{"text":"The radiator ticks quietly. The rain keeps up its gentle rhythm. Somewhere in the building, an old clock chimes the hour, and the sound rolls softly down the long corridors and fades away.","pauseSec":9},{"text":"The book rests open on your lap. Your eyes grow heavy. A thousand quiet stories surround you, all waiting patiently on their shelves, and none of them need you to do anything at all. Rest now.","pauseSec":12}]'::jsonb, 'rainy-window', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('morning-light', 'meditation', 'Morning Light', 'Morning mindfulness', 'A bright, gentle start: arrive in your body, notice the morning around you and set a simple intention for the day.', 'Nimbus', array['morning','mindfulness']::text[], array['morning','intention','energy']::text[], array['morning','mindfulness','happiness']::text[], '{"scene":"sunrise","palette":["#3b4a8f","#e9a6b4","#ffd2a6"],"sun":true}'::jsonb, '[{"text":"Good morning. Find a comfortable way to sit, with your back upright but not stiff. Let your hands rest wherever they feel natural.","pauseSec":4},{"text":"Take a slow breath in through your nose, and a long breath out. And again. Breathing in, noticing you''re awake. Breathing out, letting yourself arrive.","pauseSec":8},{"text":"Notice the sounds of the morning. Maybe birds, or traffic, or the hum of the house. You don''t need to name them or change them. Just let them be part of this moment.","pauseSec":10},{"text":"Now bring your attention to your body. The feeling of your feet on the floor. The weight of your hands. Any places that feel stiff or sleepy. Just notice, with curiosity.","pauseSec":10},{"text":"Let your breath find its own natural rhythm. You might notice it''s slightly different from a moment ago. That''s fine. Simply follow it, in and out, for a few breaths.","pauseSec":14},{"text":"As you get ready to begin your day, choose one simple intention. It might be a word, like patience, or kindness, or curiosity. Or a small wish, like I''d like to take things one step at a time.","pauseSec":10},{"text":"Hold that intention lightly, like a warm stone in your pocket. You can return to it whenever you remember.","pauseSec":6},{"text":"Take one more full breath in, and let it out slowly. When you''re ready, open your eyes, and step gently into your morning.","pauseSec":3}]'::jsonb, 'morning-meadow', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('unclench', 'meditation', 'Unclench', 'Stress reduction', 'When everything feels like too much: slow the breath, soften the places that hold tension and make a little room around stress.', 'Nimbus', array['stress','mindfulness']::text[], array['stress','tension','calm','overwhelm']::text[], array['stress','relax']::text[], '{"scene":"lake","palette":["#1a2156","#5266a8","#a9c7ee"],"landmark":"boat","sun":false}'::jsonb, '[{"text":"Welcome. If things feel busy or heavy right now, you''ve done something kind for yourself just by pausing. Let''s take a few minutes together.","pauseSec":4},{"text":"Start by noticing where you are. Feel the surface beneath you holding your weight. You don''t have to hold yourself up right now.","pauseSec":6},{"text":"Let''s take a slower breath. Breathe in for a count of four. And breathe out for a count of six. In, two, three, four. Out, two, three, four, five, six.","pauseSec":8},{"text":"Again, in at your own pace, and a long, unhurried breath out. Let the out-breath be a little longer than the in-breath, like a sigh.","pauseSec":10},{"text":"Now notice your jaw. Is it tight? Let your teeth part slightly and your tongue rest. Notice your forehead and the space between your eyebrows. Let it smooth out.","pauseSec":10},{"text":"Notice your shoulders. Many of us carry stress there. Lift them gently towards your ears, hold for a moment, and then let them fall. Let them stay a little lower.","pauseSec":10},{"text":"Notice your hands. If they''re clenched, open them. Let your fingers soften and rest.","pauseSec":8},{"text":"Stressful thoughts may still be here, and that''s alright. Imagine them as clouds passing over a wide sky. You are the sky. The clouds can move through, and the sky stays.","pauseSec":14},{"text":"Come back to the breath. In, and a long, slow out. Each out-breath, a little softer.","pauseSec":12},{"text":"Before we finish, ask yourself: what''s one small, kind thing I could do next? It might be a glass of water, a short walk, or simply taking the next task one step at a time.","pauseSec":8},{"text":"Take one last breath. You can come back to this pause whenever you need it.","pauseSec":3}]'::jsonb, 'lakeside', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('body-scan-drift', 'meditation', 'Drifting Body Scan', 'Body scan', 'A slow, kindly journey of attention from your toes to the crown of your head, letting each part of the body soften and rest.', 'Nimbus', array['body-scan','sleep-meditations']::text[], array['body scan','relaxation','sleep']::text[], array['sleep','relax','mindfulness']::text[], '{"scene":"clouds","palette":["#1b1d50","#5b5aa6","#c9b6f2"],"moon":true,"stars":true}'::jsonb, '[{"text":"Lie down or sit back comfortably, and let your eyes close if you''d like. We''re going to move our attention slowly through the body, simply noticing, without needing to change anything.","pauseSec":5},{"text":"Begin with your feet. Notice your toes, the soles of your feet, your heels. Perhaps warmth or coolness, the touch of socks or blankets. Let your feet be heavy and still.","pauseSec":12},{"text":"Let your attention drift up to your ankles and calves. Notice any tightness, and imagine your breath flowing down into these muscles, softening them as you breathe out.","pauseSec":12},{"text":"Now your knees and thighs. Strong muscles that carry you all day. Let them rest. Let them sink a little more deeply into the surface beneath you.","pauseSec":12},{"text":"Bring your attention to your hips and lower back. If there''s any ache or holding here, simply notice it, and breathe gently around it.","pauseSec":12},{"text":"Now your belly. Notice it rising as you breathe in, and falling as you breathe out. Like the gentle swell of the sea.","pauseSec":14},{"text":"Move up to your chest and upper back. Notice your heartbeat if you can feel it, steady and faithful. Let your chest feel open and easy.","pauseSec":12},{"text":"Now your shoulders, your arms, your hands, all the way to your fingertips. Let them feel heavy and warm, as though they''re melting into the bed.","pauseSec":12},{"text":"Notice your neck, and your jaw, and the little muscles around your eyes. Let them soften. Let your face be completely at rest.","pauseSec":12},{"text":"Finally, sense your whole body at once, lying here, breathing, resting. Nothing to fix. Nothing to do. Just this soft, heavy, peaceful body.","pauseSec":16},{"text":"You can stay here as long as you like, and let yourself drift towards sleep whenever you''re ready.","pauseSec":10}]'::jsonb, 'soft-piano', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('three-good-things', 'meditation', 'Three Good Things', 'Gratitude', 'Gently gather three small good things from your day and let yourself really feel them.', 'Nimbus', array['gratitude','mindfulness']::text[], array['gratitude','happiness','reflection']::text[], array['happiness','mindfulness']::text[], '{"scene":"meadow","palette":["#3a3f8c","#d79bc0","#ffd8b0"],"landmark":"tree","sun":true}'::jsonb, '[{"text":"Welcome. Let''s take a few minutes to notice some of the good things that are already here. Settle into a comfortable position and take a slow breath.","pauseSec":5},{"text":"Gratitude doesn''t need to be big. It can be very small. A warm drink. A message from a friend. The way the light looked through a window.","pauseSec":6},{"text":"Think back over today, or yesterday. Let one small good thing come to mind. There''s no wrong answer. Just let the first one appear.","pauseSec":12},{"text":"Now see if you can picture it. Where were you? What did it look like, or sound like, or feel like? Let yourself enjoy it again, just for a moment.","pauseSec":12},{"text":"Let a second good thing come to mind. Perhaps something someone did for you, or something you did for yourself. Hold it gently, and notice how it feels in your body.","pauseSec":14},{"text":"And a third. Maybe something you often take for granted. A comfortable bed. Clean water. A song you love. Let yourself appreciate it.","pauseSec":14},{"text":"Notice any warmth, softness or lightness in your body. If you don''t feel much, that''s fine too. Simply noticing is the practice.","pauseSec":8},{"text":"Take a full breath in, and let it go. You might like to write your three good things in your journal later. Thank you for taking this time.","pauseSec":3}]'::jsonb, 'morning-meadow', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('soft-landing', 'meditation', 'Soft Landing', 'Relaxation', 'Release the busyness of the day with gentle breath and a slow wave of relaxation.', 'Nimbus', array['relaxation']::text[], array['relax','unwind','calm']::text[], array['relax','stress']::text[], '{"scene":"ocean","palette":["#14205a","#4f6fb3","#f3c0a6"],"sun":true}'::jsonb, '[{"text":"Hello. Let''s make a soft landing at the end of whatever you''ve been doing. Get comfortable, and let your eyes close or rest your gaze low.","pauseSec":4},{"text":"Take a deep breath in, filling your lungs. Hold it gently at the top for a moment. And let it all go with a sigh.","pauseSec":8},{"text":"Imagine you''re lying on warm sand by a calm sea. Each wave rolls in slowly, and as it rolls out, it takes a little tension away with it.","pauseSec":10},{"text":"The next wave rolls in and washes over your feet and legs. As it pulls back, your legs feel heavy and relaxed.","pauseSec":10},{"text":"Another wave rolls gently up to your belly and chest. As it draws back, your breathing grows slower and easier.","pauseSec":10},{"text":"A wave washes softly over your shoulders, arms and hands. As it leaves, they feel warm and loose.","pauseSec":10},{"text":"One last wave rolls up over your neck and face, cool and gentle. As it slips away, your whole face softens.","pauseSec":10},{"text":"Rest here for a while, listening to the waves, letting your body be completely supported.","pauseSec":16},{"text":"When you''re ready, wiggle your fingers and toes, and slowly come back, bringing a little of this calm with you.","pauseSec":3}]'::jsonb, 'ocean-drift', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('single-point', 'meditation', 'Single Point', 'Focus', 'Train your attention with a simple anchor so you can return to your work clear and steady.', 'Nimbus', array['focus-meditations']::text[], array['focus','attention','work','study']::text[], array['focus']::text[], '{"scene":"mountains","palette":["#162a5c","#4b79b8","#b9e0f2"],"sun":true}'::jsonb, '[{"text":"Welcome. This is a short practice for gathering your attention. Sit upright, feet on the floor, and let your hands rest.","pauseSec":4},{"text":"Choose an anchor: the feeling of breath at the tip of your nose. Notice the cool air coming in, and the slightly warmer air going out.","pauseSec":8},{"text":"Now, count your breaths. Breathing in, breathing out, one. Breathing in, breathing out, two. Count up to ten, then start again at one.","pauseSec":20},{"text":"If you lose count, or find yourself planning or remembering, that''s completely normal. That moment of noticing is the exercise. Gently return to one.","pauseSec":20},{"text":"Keep going. Each time your attention wanders and you bring it back, you''re strengthening your focus, like a muscle.","pauseSec":20},{"text":"Now let go of counting. Think of the one task you''d like to give your attention to next. Picture the very first small step.","pauseSec":8},{"text":"Take one more steady breath. When you open your eyes, begin with that first small step.","pauseSec":3}]'::jsonb, 'deep-focus', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('dusk-wind-down', 'meditation', 'Dusk', 'Evening wind-down', 'Close the day kindly: notice what happened, let go of what''s unfinished and prepare your body for rest.', 'Nimbus', array['evening','sleep-meditations']::text[], array['evening','wind down','sleep','letting go']::text[], array['sleep','relax','stress']::text[], '{"scene":"mountains","palette":["#121a4c","#5a4a96","#f0a88f"],"moon":true,"stars":true}'::jsonb, '[{"text":"Good evening. The day is coming to a close. Let''s take some time to help your mind and body shift gently towards rest.","pauseSec":5},{"text":"Get comfortable, and take a slow breath in, and a long breath out. Let the out-breath carry away a little of the day''s effort.","pauseSec":8},{"text":"Let today play back softly, like a film on low volume. You don''t need to judge it or fix it. Just notice the shape of the day.","pauseSec":14},{"text":"Maybe there are things left unfinished. Imagine placing each one in a box by the door. They''ll still be there tomorrow, and you can pick them up then. For now, they can rest too.","pauseSec":14},{"text":"Is there one moment from today you''d like to keep? Let it come to mind, and hold it for a breath or two.","pauseSec":10},{"text":"Now let your body know it''s evening. Soften your forehead. Unclench your jaw. Let your shoulders slide down. Let your belly be soft.","pauseSec":12},{"text":"Breathe in for four, and out for six. In, and slowly out. With each breath out, let yourself grow a little heavier and a little more still.","pauseSec":16},{"text":"You''ve done enough for today. You can let go now, and rest.","pauseSec":8}]'::jsonb, 'soft-piano', 'original-demo', true, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('sixty-second-reset', 'meditation', 'One-Minute Reset', 'Short reset', 'A tiny pause for between meetings or before a hard conversation.', 'Nimbus', array['short-resets']::text[], array['quick','reset','work','anytime']::text[], array['stress','focus','mindfulness']::text[], '{"scene":"clouds","palette":["#2b3f8a","#7fa6e0","#cfe6ff"],"sun":true}'::jsonb, '[{"text":"Let''s take one minute. Wherever you are, pause what you''re doing and let your hands rest.","pauseSec":3},{"text":"Breathe in slowly through your nose. And out through your mouth, as if you''re blowing out a candle. Once more. In. And out.","pauseSec":8},{"text":"Notice three things you can see. Two things you can hear. One thing you can feel, like your feet on the floor.","pauseSec":12},{"text":"One last breath. In. And out. You''re ready for what''s next.","pauseSec":2}]'::jsonb, null, 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('kind-pause', 'meditation', 'A Kind Pause', 'Short reset', 'Three minutes of warmth and self-kindness for a tough moment.', 'Nimbus', array['short-resets','stress']::text[], array['self-kindness','quick','stress']::text[], array['stress','happiness']::text[], '{"scene":"lake","palette":["#24245e","#8170c2","#f4b9a3"],"landmark":"tree","sun":true}'::jsonb, '[{"text":"Hello. If this is a tough moment, let''s meet it with a little kindness. Place a hand on your chest or your arm, if that feels comfortable.","pauseSec":5},{"text":"Notice the warmth of your hand. Breathe in slowly, and out slowly.","pauseSec":8},{"text":"Silently, say to yourself: this is hard right now. Lots of people feel this way sometimes. May I be kind to myself.","pauseSec":12},{"text":"If those words don''t fit, find your own. Perhaps simply, I''m doing my best.","pauseSec":10},{"text":"Take one more slow breath. Remember that reaching out to someone you trust is a kind thing to do, too.","pauseSec":3}]'::jsonb, 'lakeside', 'original-demo', false, null, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('breathe-gentle', 'breathing', 'Gentle Paced Breathing', '5 in · 5 out', 'Slow, even breathing with a soft glowing orb to follow. A comfortable place to start.', 'Breathing Studio', array['breathwork']::text[], array['breathing','calm','anytime']::text[], array['stress','relax','mindfulness']::text[], '{"scene":"clouds","palette":["#23306e","#6f8fd6","#cfe1ff"],"sun":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 3, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('breathe-box', 'breathing', 'Box Breathing', '4 · 4 · 4 · 4', 'Four equal phases to help steady a busy mind before something important.', 'Breathing Studio', array['breathwork']::text[], array['breathing','focus','steady']::text[], array['stress','focus']::text[], '{"scene":"mountains","palette":["#1a2a66","#4c74c2","#a8d6f5"]}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 4, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('breathe-478', 'breathing', '4-7-8 Wind-Down', '4 in · 7 hold · 8 out', 'A longer out-breath that many people find soothing at bedtime. Stop any time it feels uncomfortable.', 'Breathing Studio', array['breathwork','sleep-meditations']::text[], array['breathing','sleep','evening']::text[], array['sleep','relax']::text[], '{"scene":"night","palette":["#0f1440","#3c3a86","#b6a0ef"],"moon":true,"stars":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 4, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-grounding', 'activity', '5-4-3-2-1 Grounding', 'Come back to right here', 'Notice five things you can see, four you can feel, three you can hear, two you can smell and one you can taste. Tap as you go.', 'Activity', array['activities']::text[], array['grounding','senses','anxious','present','quick']::text[], array['stress','mindfulness']::text[], '{"scene":"meadow","palette":["#24406b","#5a96a8","#cdeedc"],"sun":true,"landmark":"tree"}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 3, 'grounding') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-muscle-release', 'activity', 'Tense & Release', 'Progressive muscle relaxation', 'Gently tense one area of your body, then let it go. Six areas, guided with a timer, a glowing cue and soft chimes.', 'Activity', array['activities','relaxation']::text[], array['muscle','tension','body','relax','sleep']::text[], array['relax','sleep','stress']::text[], '{"scene":"lake","palette":["#1d1f5c","#6a5fb8","#f3b8a8"],"moon":true,"stars":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 5, 'muscle-release') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-worry-clouds', 'activity', 'Worry Clouds', 'Write it down, let it drift', 'Type what''s on your mind. Each worry becomes a little cloud you can watch drift away. Nothing you type is saved.', 'Activity', array['activities','stress']::text[], array['worry','overthinking','letting go','evening']::text[], array['stress','sleep']::text[], '{"scene":"clouds","palette":["#2b3a86","#8a8fd6","#e6dcff"],"sun":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 3, 'worry-clouds') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-gratitude-jar', 'activity', 'Gratitude Jar', 'Three small good things', 'Add three good things from today and watch them glow in your jar. Save them to your journal if you like.', 'Activity', array['activities','gratitude']::text[], array['gratitude','happiness','reflection','evening']::text[], array['happiness','habits']::text[], '{"scene":"night","palette":["#121a4c","#5a4a96","#f0a88f"],"moon":true,"stars":true,"landmark":"lantern"}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 3, 'gratitude-jar') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-gentle-stretch', 'activity', 'Gentle Stretch', 'Six easy moves, seated or standing', 'Neck, shoulders, sides, wrists, back and chest. Thirty seconds each, with a timer and a chime between moves.', 'Activity', array['activities','morning']::text[], array['stretch','movement','body','desk','morning','energy']::text[], array['morning','focus','habits']::text[], '{"scene":"sunrise","palette":["#3b4a8f","#e9a6b4","#ffd2a6"],"sun":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 4, 'gentle-stretch') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('activity-calm-bubbles', 'activity', 'Calm Bubbles', 'A slow, mindful mini-game', 'Bubbles drift up slowly. Pop them gently, one breath at a time. No score to beat, just something soothing to do with your hands.', 'Activity', array['activities']::text[], array['game','playful','anxious','focus','quick']::text[], array['stress','relax','focus']::text[], '{"scene":"ocean","palette":["#0f1c4d","#2f5ea0","#9fd3ff"],"sun":true}'::jsonb, '[]'::jsonb, null, 'original-demo', false, 2, 'calm-bubbles') on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('focus-25', 'focus', 'Deep Work · 25 min', 'Focus timer with brown noise', 'A single focused block with a soft sound bed and a gentle chime at the end.', 'Focus Studio', array['focus-sessions']::text[], array['focus','work','study','pomodoro']::text[], array['focus']::text[], '{"scene":"mountains","palette":["#162a5c","#4b79b8","#b9e0f2"],"sun":true}'::jsonb, '[]'::jsonb, 'deep-focus', 'original-demo', false, 25, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('focus-50', 'focus', 'Long Flow · 50 min', 'Focus timer with rain', 'A longer block for absorbing work, with rain on the window.', 'Focus Studio', array['focus-sessions']::text[], array['focus','work','flow']::text[], array['focus']::text[], '{"scene":"forest","palette":["#14223f","#2e5170","#86a9bd"],"landmark":"cabin"}'::jsonb, '[]'::jsonb, 'rainy-window', 'original-demo', false, 50, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('sound-rainy-window', 'soundscape', 'Rainy Window', 'Soundscape', 'Rain on glass with a low, cosy hum. Generated live in your browser, so it never loops the same way twice.', 'Soundscape Mixer', array['soundscapes']::text[], array['sounds','ambient','rain','brown-noise']::text[], array['sleep','relax']::text[], '{"scene":"forest","palette":["#14223f","#2e5170","#86a9bd"],"landmark":"cabin"}'::jsonb, '[]'::jsonb, 'rainy-window', 'original-demo', false, 30, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
insert into public.content_items (id, kind, title, subtitle, description, narrator, category_ids, tags, needs, artwork, script, ambience_preset_id, source, featured, fixed_minutes, activity_id) values ('sound-ocean-drift', 'soundscape', 'Ocean Drift', 'Soundscape', 'Waves and a soft sea breeze. Generated live in your browser, so it never loops the same way twice.', 'Soundscape Mixer', array['soundscapes']::text[], array['sounds','ambient','ocean','wind']::text[], array['sleep','relax']::text[], '{"scene":"ocean","palette":["#0f1c4d","#2f5ea0","#f2b49a"],"sun":true}'::jsonb, '[]'::jsonb, 'ocean-drift', 'original-demo', false, 30, null) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, script = excluded.script, artwork = excluded.artwork, tags = excluded.tags;
